// Independent exhaustive check of the fixed three-cube source.
//
// Build: c++ -O3 -std=c++17 independent_enumeration.cpp -o /tmp/cube_check
// Run:   /tmp/cube_check [--output report.json]
//
// No external libraries or SAT solver are used. This program generates Ls
// directly from (x,y), (x+h,y), (x+h,y+h), with h>0. In particular, the
// geometric constraints are not generated by pairing equal-offset cells.
// Every binary assignment is either visited or pruned only after an entire
// L has been assigned a single color. There is no symmetry reduction.
// This is a finite check for the displayed marks, not by itself a theorem
// for arbitrary sources or arbitrary cube weights.

#include <algorithm>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <map>
#include <numeric>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace {
using State = std::uint32_t;
constexpr int cell_count = 28;
const std::vector<int> marks{0, 1, 5, 6, 25, 26, 30, 31};
std::vector<std::pair<int, int>> cells;
std::vector<State> corners;
std::vector<State> fibers;
std::vector<std::vector<State>> incident(cell_count);
std::vector<int> ordering;
std::vector<State> proper_states;
std::map<int, std::uint64_t> phi_histogram;
std::map<int, std::uint64_t> local_minimum_histogram;

int popcount(State value) {
    // Kernighan's algorithm keeps the program within portable C++17.
    int count = 0;
    while (value != 0) {
        value &= value - 1;
        ++count;
    }
    return count;
}

int phi(State state) {
    int result = 0;
    for (State fiber : fibers) {
        const int imbalance = popcount(fiber) - 2 * popcount(fiber & state);
        result += imbalance * imbalance;
    }
    return result;
}

bool is_legal_after_flip(State state, int flipped_cell) {
    // All unaffected corners remain proper from the original proper state.
    for (State corner : incident[flipped_cell]) {
        const State ones = state & corner;
        if (ones == 0 || ones == corner) return false;
    }
    return true;
}

void enumerate(int depth, State assigned, State state) {
    if (depth == cell_count) {
        ++phi_histogram[phi(state)];
        proper_states.push_back(state);
        return;
    }
    const int cell = ordering[depth];
    const State bit = State{1} << cell;
    const State next_assigned = assigned | bit;
    for (int color = 0; color < 2; ++color) {
        const State next_state = state | (color == 1 ? bit : 0);
        bool proper = true;
        for (State corner : incident[cell]) {
            if ((corner & next_assigned) != corner) continue;
            const State ones = corner & next_state;
            if (ones == 0 || ones == corner) {
                proper = false;
                break;
            }
        }
        if (proper) enumerate(depth + 1, next_assigned, next_state);
    }
}

void build_geometry() {
    std::map<std::pair<int, int>, int> index;
    for (int v : marks) {
        for (int u : marks) {
            if (u >= v) continue;
            index[{v, u}] = static_cast<int>(cells.size());
            cells.emplace_back(v, u);
        }
    }
    if (cells.size() != cell_count) throw std::logic_error("Wrong cell count");

    for (int first = 0; first < cell_count; ++first) {
        const auto [x, y] = cells[first];
        for (int step = 1; x + step <= marks.back(); ++step) {
            const auto second = index.find({x + step, y});
            const auto third = index.find({x + step, y + step});
            if (second == index.end() || third == index.end()) continue;
            const State corner = (State{1} << first)
                | (State{1} << second->second) | (State{1} << third->second);
            corners.push_back(corner);
            for (int cell : {first, second->second, third->second}) {
                incident[cell].push_back(corner);
            }
        }
    }

    std::map<int, State> by_offset;
    for (int cell = 0; cell < cell_count; ++cell) {
        by_offset[cells[cell].first - cells[cell].second] |= State{1} << cell;
    }
    for (const auto& entry : by_offset) fibers.push_back(entry.second);

    ordering.resize(cell_count);
    std::iota(ordering.begin(), ordering.end(), 0);
    // Search high-degree cells first; only the visit order changes.
    std::stable_sort(ordering.begin(), ordering.end(), [](int a, int b) {
        return incident[a].size() > incident[b].size();
    });
}

void print_histogram(std::ostream& out,
                     const std::map<int, std::uint64_t>& histogram) {
    out << '{';
    bool first = true;
    for (const auto& [value, count] : histogram) {
        if (!first) out << ", ";
        first = false;
        out << '"' << value << "\": " << count;
    }
    out << '}';
}

void write_report(std::ostream& out) {
    if (proper_states.empty()) throw std::logic_error("No proper colorings");
    const int minimum = phi_histogram.begin()->first;
    const int maximum = phi_histogram.rbegin()->first;
    std::uint64_t state_sum = 0;
    State state_xor = 0;
    std::uint64_t failures = 0;
    for (State state : proper_states) {
        state_sum += state;
        state_xor ^= state;
        const int value = phi(state);
        bool has_decreasing_flip = false;
        for (int cell = 0; cell < cell_count; ++cell) {
            const State neighbor = state ^ (State{1} << cell);
            if (phi(neighbor) < value && is_legal_after_flip(neighbor, cell)) {
                has_decreasing_flip = true;
                break;
            }
        }
        if (!has_decreasing_flip) {
            ++local_minimum_histogram[value];
            if (value > minimum) ++failures;
        }
    }

    out << "{\n  \"scope\": \"All proper binary colorings of the fixed source; no symmetry quotient\",\n";
    out << "  \"marks\": [0, 1, 5, 6, 25, 26, 30, 31],\n";
    out << "  \"state_encoding\": \"Bit i is the color of cells[i]; cells ordered by v then u\",\n";
    out << "  \"cells\": [";
    for (int i = 0; i < cell_count; ++i) {
        if (i != 0) out << ", ";
        out << '[' << cells[i].first << ", " << cells[i].second << ']';
    }
    out << "],\n  \"cell_count\": " << cells.size()
        << ",\n  \"corner_count\": " << corners.size()
        << ",\n  \"fiber_count\": " << fibers.size()
        << ",\n  \"proper_coloring_count\": " << proper_states.size()
        << ",\n  \"minimum_phi\": " << minimum
        << ",\n  \"maximum_phi\": " << maximum
        << ",\n  \"phi_histogram\": ";
    print_histogram(out, phi_histogram);
    out << ",\n  \"no_strictly_decreasing_legal_single_flip_histogram\": ";
    print_histogram(out, local_minimum_histogram);
    out << ",\n  \"nonoptimal_states_without_decreasing_flip\": " << failures
        << ",\n  \"state_sum\": " << state_sum
        << ",\n  \"state_xor\": " << state_xor
        << ",\n  \"checksum_scope\": \"Sum and xor are auxiliary comparisons, not cryptographic hashes\"\n}\n";
}
}  // namespace

int main(int argc, char** argv) {
    try {
        if (argc != 1 && !(argc == 3 && std::string(argv[1]) == "--output")) {
            std::cerr << "Usage: " << argv[0] << " [--output report.json]\n";
            return 2;
        }
        build_geometry();
        enumerate(0, 0, 0);
        if (argc == 3) {
            std::ofstream out(argv[2]);
            if (!out) throw std::runtime_error("Cannot open output file");
            write_report(out);
            if (!out) throw std::runtime_error("Cannot write output file");
        } else {
            write_report(std::cout);
        }
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
